//! Authored only. Pure mapping/refusal fixtures; no native acceptance fabricated.
use super::*;
fn fixture()->(tempfile::TempDir,Request,RecoveredInput){let (root,c,carrier)=recovered::tests::fixture();let input=RecoveredInput {binding:recovered::RecoveredBinding {carrier_directory:"/synthetic/carrier".into(),carrier_sha256:"a".repeat(64)},carrier};let r=Request {schema:"aniflow.chunked-recovered-rife-request/v1".into(),base:RecoveredRifeRequest {schema:"aniflow.recovered-rife-request/v1".into(),source:input.binding.clone(),configuration:c,provider_executable:"/synthetic/provider".into()},output_frames_per_chunk:2};(root,r,input)}
fn output(r:&Request,input:&RecoveredInput,range:(u64,u64))->RifeOutputIndex {let plan=recovered::plan(&r.base.configuration,&input.carrier).unwrap();let mut frames=super::super::provider::output_frame_template(&plan).unwrap();for f in &mut frames{f.sha256=if f.origin==RifeFrameOrigin::InterpolatedMidpoint{"9".repeat(64)}else{input.carrier.selection.frames[f.source_left_ordinal as usize].sha256.clone()};}RifeOutputIndex {schema:CHUNK_SCHEMA.into(),plan,frames:frames[range.0 as usize..range.1 as usize].to_vec()}}
fn op(r:Request,range:(u64,u64))->Operation{Operation {schema:"aniflow.rife-chunk-operation/v1".into(),request:r,role:Role::Chunk {first_output:range.0,end_output:range.1}}}
#[test] fn bounded_ranges_cover_once_and_large_realistic_clock_has_many_checkpoints(){let p=ranges(11204,128).unwrap();assert_eq!(p.len(),88);assert_eq!(p.first(),Some(&(0,128)));assert_eq!(p.last(),Some(&(11136,11204)));assert!(p.windows(2).all(|w|w[0].1==w[1].0));assert!(ranges(32770,256).is_err());for limit in [0,1,3,258]{assert!(ranges(12,limit).is_err());}}
#[test] fn chunks_retain_global_mapping_original_holds_and_full_clock(){let (_root,r,input)=fixture();let p=recovered::plan(&r.base.configuration,&input.carrier).unwrap();for range in ranges(p.output_frame_count,2).unwrap(){let out=output(&r,&input,range);chunk_output(&op(r.clone(),range),&input,&out).unwrap();assert_eq!(out.plan,p);assert_eq!(out.frames[0].ordinal,range.0);}}
#[test] fn changed_held_hash_duplicate_or_missing_frame_cannot_form_a_chunk(){let (_root,r,input)=fixture();let op=op(r.clone(),(0,2));let out=output(&r,&input,(0,2));let mut changed=out.clone();changed.frames[0].sha256="8".repeat(64);assert!(chunk_output(&op,&input,&changed).is_err());let mut missing=out.clone();missing.frames.pop();assert!(chunk_output(&op,&input,&missing).is_err());let mut duplicate=out.clone();duplicate.frames[1]=duplicate.frames[0].clone();assert!(chunk_output(&op,&input,&duplicate).is_err());}
#[test] fn partial_output_never_pretends_to_be_complete_legacy_evidence(){let (_root,r,input)=fixture();let out=output(&r,&input,(0,2));assert!(recovered::validate_output(&out,&r.base.configuration,&input.carrier).is_err());let mut wrong=out;wrong.schema=recovered::OUTPUT_SCHEMA.into();assert!(chunk_output(&op(r,(0,2)),&input,&wrong).is_err());}
#[test] fn regrouping_changes_closed_configuration_and_unknown_fields_refuse(){let (_root,r,_input)=fixture();let a=op(r.clone(),(0,2)).configuration().unwrap();let mut other=r.clone();other.output_frames_per_chunk=4;let b=op(other,(0,4)).configuration().unwrap();assert_ne!(a,b);let mut v=serde_json::to_value(r).unwrap();v["adopt_existing_frames"]=serde_json::json!(true);assert!(Request::from_json_slice(&serde_json::to_vec(&v).unwrap()).is_err());}
#[test] fn unknown_root_is_preserved_and_never_promoted_to_native_work(){let root=tempfile::tempdir().unwrap();let root=root.path().canonicalize().unwrap();std::fs::write(root.join("old.png"),b"private loose pixels").unwrap();assert!(status(&root,&CancellationToken::new()).is_err());assert!(resume(&root,&CancellationToken::new(),|_|{}).is_err());assert_eq!(std::fs::read(root.join("old.png")).unwrap(),b"private loose pixels");assert!(!root.join("children").exists());}
